def _text(k, a, b):
    return "(" + " and ".join(KIND[c] for c in k) + ") " + a + " **Second pick.** " + b
POOL = [[n, _text(k, a, b), fx] for n, k, a, b, fx in _P]
OPTS = {"label": "Heritage Traits", "n": 8, "list": POOL}

def _opts():
    return {"label": OPTS["label"], "n": 8, "list": [list(x) for x in POOL]}

_SWAP = " You can swap any traditional trait for another from the pool, take a trait twice for its second effect, or use the traditional traits of another heritage."
_SPD = " You can lower your Speed by 5 feet to gain one extra trait."
_SPD_S = " If you are Small, you can lower your Speed by 5 feet to gain one extra trait."

def _mk(size, speed, traits, trad, extra="", fx=None, lowspeed=True):
    if lowspeed is True and "or" in size: lowspeed = "S"
    t = [["Heritage Traits", "Pick eight traits from the Heritage Traits list. The traditional picks for this heritage are: " + trad + "." + _SWAP + (_SPD_S if lowspeed == "S" else _SPD if lowspeed else "")]]
    r = {"size": size, "speed": speed, "dark": 0, "type": "Humanoid", "traits": traits + t, "opts": _opts(), "hb": "TGHP"}
    if fx: r["fx"] = fx
    return r

def _age(s): return [["Age", s]]
def _std(trad, age, size="Medium", speed=30, extra=None, fx=None, lowspeed=False):
    return _mk(size, speed, _age(age) + (extra or []), trad, fx=fx, lowspeed=lowspeed)

